arguments.command:
python3 -c "
from defusedxml.minidom import parse
doc = parse('unpacked/word/document.xml')
body = doc.getElementsByTagName('w:body')[0]
paras = body.getElementsByTagName('w:p')
# Print text and full rPr details + attributes for each paragraph
for i, p in enumerate(paras):
    texts=[]
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild: texts.append(t.firstChild.data)
    text=''.join(texts)
    rprs = p.getElementsByTagName('w:rPr')
    details=[]
    for rpr in rprs:
        detail=[]
        for child in rpr.childNodes:
            if child.nodeType==1:
                attr=''
                for k,v in child.attributes.items():
                    attr += f' {k}={v}'
                detail.append(child.tagName+attr)
        details.append(';'.join(detail))
    # check pPr attributes
    pPrs = p.getElementsByTagName('w:pPr')
    ppinfo=[]
    for pPr in pPrs:
        for child in pPr.childNodes:
            if child.nodeType==1:
                ppinfo.append(child.tagName)
    print(f'[{i}] rPr[{len(rprs)}]={details[:2]} pPr={ppinfo} text={text[:70]!r}')
"
